// Cyrus limits: a plain CONSEQUENCE for a setting that declares none. Heuristics from the key / label / unit, so every
// warning says what is likely to happen ("work grows with the square of the radius") instead of only "out of range".
// A spec that knows better declares `impact` itself (ChunkMirror: "mirrored changes per block"). Pure.
import type { Impact } from "./range";

const has = (s: string, re: RegExp) => re.test(s.toLowerCase());

/** A best-guess impact model for a setting, or undefined when nothing sensible can be said. */
export function inferImpact(key: string, label = "", unit = ""): Impact | undefined {
  const s = `${key} ${label}`.replace(/[_.-]/g, " ");
  const u = unit.toLowerCase();
  if (has(s, /\b(radius|range|distance|reach|area)\b/)) {
    if (/chunk/.test(u) || has(s, /\bchunks?\b/)) return { model: "square", factor: 4, unit: "chunks covered around each player", note: "work and memory grow with the square of the radius; expect lag on most servers; the TPS safety net can pause it" };
    return { model: "cube", factor: 8, unit: "blocks searched", note: "work grows with the cube of a block radius; expect lag when this runs often; the TPS safety net can pause it" };
  }
  if (has(s, /\b(per tick|per-tick|batch|per cycle|work)\b/)) return { model: "linear", factor: 20, unit: "work units per second", note: "more work every tick; a busy server may drop below 20 TPS; the TPS safety net can pause it" };
  if (has(s, /\b(period|interval|every)\b/) && /tick/.test(u + s)) return { model: "inverse", factor: 20, unit: "runs per second", note: "runs more often; a short interval with heavy work causes lag" };
  if (has(s, /\b(particles?)\b/)) return { model: "linear", factor: 1, unit: "particles each time", note: "many particles lag players' clients before the server" };
  if (has(s, /\b(spawn|mobs?|entities|entity|minions?|copies|count|amount|max)\b/)) return { model: "linear", factor: 1, unit: "at a time", note: "more entities or items means more server work and memory; the TPS safety net can pause heavy features" };
  if (has(s, /\b(damage|health|hp|heal|armor|strength|knockback)\b/)) return { model: "linear", factor: 1, unit: "", note: "a big jump in power changes how the game feels; nothing breaks" };
  return undefined;
}

/** The impact's own line without the leading "v = n unit" part (when the computed number would read oddly). */
export const impactNote = (i: Impact | undefined) => i?.note;

